46	    uint32_t aivNum;
47	    uint32_t aicNum;
48	    uint64_t ubSize;
49	    uint64_t l1Size;
50	    uint64_t l0aSize;
51	    uint64_t l0bSize;
52	    uint64_t l0cSize;
