160	        oss << "(shape:" << GetShapeDebugStr(shape->GetStorageShape()) << "),";
161	        oss << "(ori_shape:" << GetShapeDebugStr(shape->GetOriginShape()) << "),";
162	        oss << "(format: "
163	            << ge::TypeUtils::FormatToSerialString(
164	                   static_cast<ge::Format>(ge::GetPrimaryFormat(tensor->GetStorageFormat())))
165	            << "),";
166	        oss << "(ori_format: " << ge::TypeUtils::FormatToSerialString(tensor->GetOriginFormat()) << ") ";
167	        return oss.str();
