11	/*!
12	 * \file tiling_templates_registry.h
13	 * \brief
14	 */
15	
16	#ifndef TILING_TEMPLATES_REGISTRY_H
17	#define TILING_TEMPLATES_REGISTRY_H
18	
19	#include <map>
20	#include <string>
21	#include <memory>
22	#include "exe_graph/runtime/tiling_context.h"
23	#include "tiling_base.h"
24	
25	namespace Ops {
26	namespace Transformer {
27	namespace OpTiling {
28	
29	template <typename T>
30	inline std::unique_ptr<TilingBaseClass> TILING_CLASS(gert::TilingContext* context)
31	{
32	    return std::unique_ptr<T>(new (std::nothrow) T(context));
33	}
34	
35	using TilingClassCase = std::unique_ptr<TilingBaseClass> (*)(gert::TilingContext*);
36	
37	class TilingCases {
38	public:
39	    explicit TilingCases(std::string op_type) : op_type_(std::move(op_type))
40	    {}
41	
42	    template <typename T>
43	    inline void AddTiling(int32_t priority)
44	    {
45	        OP_CHECK_IF(
46	            cases_.find(priority) != cases_.end(), OP_LOGE(op_type_, "There are duplicate registrations."), return);
47	        cases_[priority] = TILING_CLASS<T>;
48	        OP_CHECK_IF(
49	            cases_[priority] == nullptr,
50	            OP_LOGE(op_type_, "Register op tiling func failed, please check the class name."), return);
51	    }
52	
53	    const std::map<int32_t, TilingClassCase>& GetTilingCases()
54	    {
55	        return cases_;
56	    }
57	
58	private:
59	    std::map<int32_t, TilingClassCase> cases_;
60	    const std::string op_type_;
61	};
62	
63	// --------------------------------Interfacce with soc version --------------------------------
64	class TilingRegistryNew {
65	public:
66	    TilingRegistryNew() = default;
67	
68	#ifdef ASCENDC_OP_TEST
69	    static TilingRegistryNew& GetInstance();
70	#else
71	    static TilingRegistryNew& GetInstance()
72	    {
73	        static TilingRegistryNew registryImpl;
74	        return registryImpl;
75	    }
76	#endif
77	
78	    std::shared_ptr<TilingCases> RegisterOp(const std::string& op_type, const int32_t soc_version)
79	    {
80	        auto soc_iter = registry_map_.find(soc_version);
81	        if (soc_iter == registry_map_.end()) {
82	            std::map<std::string, std::shared_ptr<TilingCases>> op_type_map;
83	            op_type_map[op_type] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(op_type));
84	            registry_map_[soc_version] = op_type_map;
85	        } else {
86	            if (soc_iter->second.find(op_type) == soc_iter->second.end()) {
87	                soc_iter->second[op_type] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(op_type));
88	            }
89	        }
90	
91	        OP_CHECK_IF(
92	            registry_map_[soc_version][op_type] == nullptr,
93	            OP_LOGE(op_type, "Register tiling func failed, please check the class name."), return nullptr);
94	        return registry_map_[soc_version][op_type];
95	    }
96	
97	    ge::graphStatus DoTilingImpl(gert::TilingContext* context)
98	    {
99	        int32_t soc_version = (int32_t)platform_ascendc::SocVersion::RESERVED_VERSION;
100	        const char* opType = context->GetNodeType();
101	        fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
102	        if (platformInfoPtr == nullptr) {
103	            auto compileInfoPtr = static_cast<const CompileInfoCommon*>(context->GetCompileInfo());
104	            OP_CHECK_IF(
105	                compileInfoPtr == nullptr, OP_LOGE(opType, "compileInfoPtr is null."), return ge::GRAPH_FAILED);
106	            soc_version = compileInfoPtr->socVersion;
107	            OP_LOGD(context, "soc version in compileInfo is %d", soc_version);
108	        } else {
109	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
110	            soc_version = static_cast<int32_t>(ascendcPlatform.GetSocVersion());
111	            OP_LOGD(context, "soc version is %d", soc_version);
112	            if (soc_version == (int32_t)platform_ascendc::SocVersion::RESERVED_VERSION) {
113	                OP_LOGE(opType, "Do op tiling failed, cannot find soc version.");
114	                return ge::GRAPH_FAILED;
115	            }
116	        }
117	        auto tilingTemplateRegistryMap = GetTilingTemplates(opType, soc_version);
118	        for (auto it = tilingTemplateRegistryMap.begin(); it != tilingTemplateRegistryMap.end(); ++it) {
119	            auto tilingTemplate = it->second(context);
120	            if (tilingTemplate != nullptr) {
121	                ge::graphStatus status = tilingTemplate->DoTiling();
122	                if (status != ge::GRAPH_PARAM_INVALID) {
123	                    OP_LOGD(context, "Do general op tiling success priority=%d", it->first);
124	                    return status;
125	                }
126	                OP_LOGD(context, "Ignore general op tiling priority=%d", it->first);
127	            }
128	        }
129	        OP_LOGE(opType, "Do op tiling failed, no valid template is found.");
130	        return ge::GRAPH_FAILED;
131	    }
132	
