41	  uint32_t tmp_key;
42	  // Read in blocks of 4
43	  for (uint32_t i = len >> 2UL; i > 0UL; i--) {
44	    // Get a source of differing results across endiannesses.
45	    tmp_key = *key;
46	    key++;
47	    hash_key ^= MurmurScramble(tmp_key);
48	    hash_key = (hash_key << kRolBodyLeft) | (hash_key >> kRolBodyRight);
49	    hash_key = hash_key * kChunkOffset + 0xe6546b64;
