61	  hash_key ^= hash_key >> kReadSize;
62	  hash_key *= static_cast<uint32_t>(0x85ebca6b);
63	  hash_key ^= hash_key >> kRolTailRight;
64	  hash_key *= static_cast<uint32_t>(0xc2b2ae35);
65	  hash_key ^= hash_key >> kReadSize;
